const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const S = data[idx++];
const T = data[idx++];
const P = data[idx++] - 1;

const height = data.slice(idx, idx + S);
idx += S;

const graph = Array.from({ length: S }, () => []);

for (let i = 0; i < T; i++) {
  const u = data[idx++] - 1;
  const v = data[idx++] - 1;
  graph[u].push(v);
  graph[v].push(u);
}

const memo = Array(S).fill(-1);

function longestPath(u) {
  if (memo[u] !== -1) return memo[u];

  let best = 0;
  for (const v of graph[u]) {
    if (height[v] < height[u]) {
      best = Math.max(best, 1 + longestPath(v));
    }
  }

  memo[u] = best;
  return best;
}

